class Solution { public int minOperationsMaxProfit(int[] customers,int boardingCost,int runningCost){int waiting=0,profit=0,maximum=0,best=-1,rotation=0;while(rotation<customers.length||waiting>0){if(rotation<customers.length)waiting+=customers[rotation];int boarded=Math.min(4,waiting);waiting-=boarded;profit+=boarded*boardingCost-runningCost;rotation++;if(profit>maximum){maximum=profit;best=rotation;}}return best;} }
